/**
 * Embedded Lightweight Barcode Generator (JsBarcode compatible API)
 * Supports CODE128, CODE39, EAN13, EAN8
 */
(function(root) {
  function encodeCode128(text) {
    const B_TABLE = [
      "212222","222122","222221","121223","121322","131222","122213","122312","132212","221213",
      "221312","231212","112232","122132","122231","113222","123122","123221","223211","221132",
      "221231","213212","223112","312131","311222","321122","321221","312212","322112","322211",
      "212123","212321","201500","111323","131123","131321","112313","132113","132311","211313",
      "231113","231311","112133","112331","132131","113123","113321","133121","313121","211331",
      "231131","213113","213311","213131","311123","311321","331121","312113","312311","332111",
      "314111","221411","431111","111224","111422","121124","121421","141122","141221","112214",
      "112412","122114","122411","142112","142211","241211","221114","413111","241112","134111",
      "111242","121142","121241","114212","124112","124211","411212","421112","421211","212141",
      "214121","412121","111143","111341","131141","114113","114311","411113","411311","113141",
      "114131","311141","411131","211412","211214","211232","2331112"
    ];

    let codePattern = "";
    let checksum = 104; // Start Code B
    codePattern += B_TABLE[104];

    let str = String(text || "");
    for (let i = 0; i < str.length; i++) {
      let code = str.charCodeAt(i) - 32;
      if (code < 0 || code > 95) code = 0;
      checksum += code * (i + 1);
      codePattern += B_TABLE[code];
    }

    let checkIndex = checksum % 103;
    codePattern += B_TABLE[checkIndex];
    codePattern += "2331112"; // Stop pattern

    return codePattern;
  }

  function renderSVG(selectorOrElem, text, options) {
    options = Object.assign({
      format: "CODE128",
      width: 2,
      height: 50,
      displayValue: true,
      fontSize: 14,
      font: "monospace",
      textAlign: "center",
      background: "#ffffff",
      lineColor: "#000000",
      margin: 5
    }, options);

    let elem = typeof selectorOrElem === "string" ? document.querySelector(selectorOrElem) : selectorOrElem;
    if (!elem) return "";

    let binaryPattern = encodeCode128(text || "123456");
    let moduleWidth = options.width || 2;
    let barcodeWidth = 0;
    for (let char of binaryPattern) {
      barcodeWidth += parseInt(char, 10) * moduleWidth;
    }

    let quietZone = options.margin * 2;
    let totalWidth = barcodeWidth + quietZone;
    let textHeight = options.displayValue ? options.fontSize + 6 : 0;
    let totalHeight = options.height + textHeight + (options.margin * 2);

    let svgHtml = `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ${totalWidth} ${totalHeight}" preserveAspectRatio="none">
      <rect width="100%" height="100%" fill="${options.background}"/>
      <g transform="translate(${options.margin}, ${options.margin})">`;

    let x = 0;
    for (let i = 0; i < binaryPattern.length; i++) {
      let w = parseInt(binaryPattern[i], 10) * moduleWidth;
      if (i % 2 === 0) {
        svgHtml += `<rect x="${x}" y="0" width="${w}" height="${options.height}" fill="${options.lineColor}"/>`;
      }
      x += w;
    }

    if (options.displayValue) {
      let textX = barcodeWidth / 2;
      let textY = options.height + options.fontSize;
      svgHtml += `<text x="${textX}" y="${textY}" text-anchor="middle" font-family="${options.font}" font-size="${options.fontSize}" fill="${options.lineColor}">${text}</text>`;
    }

    svgHtml += `</g></svg>`;

    if (elem.tagName && elem.tagName.toLowerCase() === 'img') {
      elem.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svgHtml);
    } else if (elem.innerHTML !== undefined) {
      elem.innerHTML = svgHtml;
    }
    return svgHtml;
  }

  function JsBarcode(selector, text, options) {
    return renderSVG(selector, text, options);
  }

  JsBarcode.getSVG = function(text, options) {
    let dummy = document.createElement('div');
    return renderSVG(dummy, text, options);
  };

  root.JsBarcode = JsBarcode;
})(window);
